package ir.orix.school.assessment.domain;
import java.math.BigDecimal; import java.time.Instant; import jakarta.persistence.*; import ir.orix.school.identity.domain.UserAccount; import ir.orix.school.organization.domain.Tenant;
@Entity @Table(name="grade_history",schema="school")
public class GradeHistory { @Id @GeneratedValue(strategy = GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="tenant_id") private Tenant tenant; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="result_id") private AssessmentResult result; @Column(name="previous_total",nullable=false) private BigDecimal previousTotal; @Column(name="new_total",nullable=false) private BigDecimal newTotal; @Column(nullable=false,length=500) private String reason; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="changed_by") private UserAccount changedBy; @Column(name="changed_at",nullable=false) private Instant changedAt; protected GradeHistory(){} public GradeHistory(Tenant t,AssessmentResult r,BigDecimal before,BigDecimal after,String reason,UserAccount actor,Instant now){tenant=t;result=r;previousTotal=before;newTotal=after;this.reason=reason.strip();changedBy=actor;changedAt=now;} }
